43	export const loader = async ({ request }: LoaderFunctionArgs) => {
44	  const { session, admin } = await authenticate.admin(request);
45	  const shop = session.shop;
46	
47	  const [subscription, zipCount, deliveryRuleCount, waitlistCount, blockedZipCount, shopSettings, shopResponse] = await Promise.all([
48	    getShopSubscription(shop),
49	    db.zipCode.count({ where: { shop } }),
50	    db.deliveryRule.count({ where: { shop } }),
51	    db.waitlistEntry.count({ where: { shop } }),
52	    db.zipCode.count({ where: { shop, type: "blocked" } }),
53	    db.shopSettings.findUnique({ where: { shop } }),
54	    admin.graphql(`{ shop { name } }`),
55	  ]);
56	
57	  const shopData = await shopResponse.json();
58	  const shopName: string = shopData.data?.shop?.name ?? shop.replace(".myshopify.com", "");
59	
60	  // Cache the shop display name so email service can use it without API calls
61	  await db.shopSettings.upsert({
62	    where: { shop },
63	    create: { shop, shopName },
64	    update: { shopName },
65	  });
66	
67	  return {
68	    subscription,
69	    zipCount,
70	    deliveryRuleCount,
71	    waitlistCount,
72	    blockedZipCount,
73	    shop,
74	    shopName,
75	    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
76	    notificationEmail: shopSettings?.notificationEmail ?? "",
77	    emailSenderName: shopSettings?.emailSenderName ?? "",
78	    emailReplyTo: shopSettings?.emailReplyTo ?? "",
79	  };
80	};
