308	// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
309	// Handles @keyframes/@font-face (pass-through), @media (recursive scoping),
310	// and regular selectors (prefixed with container ID).
311	function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
312	  if (!rawCss) return "";
313	  // Sanitize the same way the public API does (mirrors api.widget-config.tsx)
314	  const css = rawCss
315	    .replace(/<style\b[^>]*>/gi, "")
316	    .replace(/<\/style>/gi, "")
317	    .replace(/@import\b[^;]*(;|$)/gi, "")
318	    .replace(/\bexpression\s*\(/gi, "")
319	    .replace(/url\s*\(\s*['"]?\s*javascript\s*:/gi, "url(")
320	    .replace(/url\s*\(\s*['"]?\s*data\s*:/gi, "url(");
321	  let result = "";
322	  let i = 0;
323	  while (i < css.length) {
324	    // Skip whitespace
325	    while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
326	    if (i >= css.length) break;
327	    // Handle at-rules
328	    if (css[i] === "@") {
329	      let atRule = "";
330	      let j = i;
331	      while (j < css.length && css[j] !== "{" && css[j] !== ";") { atRule += css[j]; j++; }
332	      const atName = atRule.trim().toLowerCase();
333	      // @keyframes and @font-face: pass through without scoping
334	      if (atName.startsWith("@keyframes") || atName.startsWith("@font-face")) {
335	        result += atRule;
336	        if (j < css.length && css[j] === "{") {
337	          let depth = 1; result += css[j]; j++;
338	          while (j < css.length && depth > 0) {
339	            if (css[j] === "{") depth++;
340	            if (css[j] === "}") depth--;
341	            result += css[j]; j++;
342	          }
343	        }
344	        i = j; continue;
345	      }
346	      // @media: recursively scope inner rules
347	      if (atName.startsWith("@media")) {
348	        result += atRule;
349	        if (j < css.length && css[j] === "{") {
350	          result += "{"; j++;
351	          let depth = 1; let inner = "";
352	          while (j < css.length && depth > 0) {
353	            if (css[j] === "{") depth++;
354	            if (css[j] === "}") depth--;
355	            if (depth > 0) inner += css[j];
356	            j++;
357	          }
358	          result += scopeAdminCss(inner, wid);
359	          result += "}";
360	        }
361	        i = j; continue;
362	      }
363	    }
364	    // Regular rule: grab selector, prefix with #wid
365	    let sel = "";
366	    let body = "";
367	    while (i < css.length && css[i] !== "{") { sel += css[i]; i++; }
368	    if (i < css.length) i++; // skip {
369	    let depth = 1;
370	    while (i < css.length && depth > 0) {
371	      if (css[i] === "{") depth++;
372	      if (css[i] === "}") depth--;
373	      if (depth > 0) body += css[i];
374	      i++;
375	    }
376	    if (sel.trim()) {
377	      const prefixed = sel.split(",").map(s => {
378	        s = s.trim();
379	        return s ? "#" + wid + " " + s : "";
380	      }).filter(Boolean).join(", ");
381	      result += prefixed + " {" + body + "}";
382	    }
383	  }
384	  return result;
385	}
